sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // Add your code here
    try { //MSSCOLATRL-268
        var groupGr = new GlideRecord('sys_user_grmember');
		groupGr.addEncodedQuery('user='+ gs.getUserID() +'^group.nameLIKERead-Only-Non-Seg');
        groupGr.query();
        if (groupGr.next()) {
            restrictForNonSegCases();
        } else {
            restrictCases();
        }
    } catch (e) {
        gs.error('Error in Business Rule MSS Collateral Case Query :' + e.message);
    }

    function restrictCases() {


        var userID = gs.getUserID();
        var userTeams = [];

        var teamMap = {
            'Margin': 'collateral_margin',
            'Interest': 'collateral_interest',
            'Settlement': 'collateral_settlement'
        };

        var groupGr = new GlideRecord('sys_user_grmember');
        groupGr.addQuery('user', userID);
        groupGr.query();
        while (groupGr.next()) {
            var groupName = groupGr.group.name.toString();
            var parts = groupName.split('-');
            if (parts.length >= 3) {
                var keyword = parts[parts.length - 2];
                var fullTeam = teamMap[keyword];
                if (fullTeam && userTeams.indexOf(fullTeam) === -1) {
                    userTeams.push(fullTeam);
                }
            }

        }


        var userGr = new GlideRecord('sys_user');
        userGr.get(userID);

        // gs.info('User sys task' + userGr.sys_id);

        var locationAccess = userGr.getValue('u_associated_managing_locations').toLowerCase();

        current.addQuery('u_assignment_team', 'IN', userTeams.join(','));

        if (locationAccess.length > 0) {
            current.addQuery('managing_location', 'IN', locationAccess);
        } else {
            current.addQuery('sys_id', 'IS', 'EMPTY');
        }

        // gs.info('Encoded Query: ' + current.getEncodedQuery());
        // gs.info('User Id:' + gs.getUserID());
        // gs.info('User Teams: ' + userTeams.join(', '));
        // gs.info('Managing Locations task: ', userGr.getValue('u_associated_managing_locations'));

    }

    //MSSCOLATRL-268
    function restrictForNonSegCases() {
        var userID = gs.getUserID();
        var userGr = new GlideRecord('sys_user');
        userGr.get(userID);
        var locationAccess = userGr.getValue('u_associated_managing_locations').toLowerCase();
        if (locationAccess.length > 0) {
            current.addQuery('managing_location', 'IN', locationAccess).addOrCondition('managing_location','');
        } else {
            current.addQuery('sys_id', 'IS', 'EMPTY');
        }
    }

})(current, previous);
